function validRemoteData(d){
 return d&&typeof d==="object"&&Array.isArray(d.tasks)&&
   (Array.isArray(d.history)||d.history==null)&&
   (Array.isArray(d.contributions)||d.contributions==null)
}
function remoteSyncVersion(d){
 const n=Number(d?.syncVersion||0);
 if(Number.isFinite(n)&&n>0)return n;
 const t=Date.parse(d?.updatedAt||"");
 return Number.isFinite(t)?t:0
}
async function refreshFromGithubData(){
 try{
   const res=await fetch(`./due-data.json?ts=${Date.now()}`,{cache:"no-store"});
   if(!res.ok)throw new Error(`HTTP ${res.status}`);
   const remote=await res.json();
   if(!validRemoteData(remote))throw new Error("Invalid due-data.json");
   const rv=remoteSyncVersion(remote);
   const lv=Number(state.settings?.githubSyncVersion||state.syncVersion||0);

   // Only a newer exported GitHub file replaces local working data.
   if(rv>lv || (!state.tasks.length && rv>=lv)){
     const incoming=normalizeLocalState(remote);
     incoming.syncVersion=rv;
     incoming.settings={
       ...(incoming.settings||{}),
       githubSyncVersion:rv,
       githubLastSyncAt:new Date().toISOString(),
       githubLastSyncStatus:"ok"
     };
     state=incoming;
     localStorage.setItem(KEY,JSON.stringify(state));
     renderAll();
     toast("Updated from GitHub");
   }else{
     state.settings=state.settings||{};
     state.settings.githubLastSyncAt=new Date().toISOString();
     state.settings.githubLastSyncStatus="up-to-date";
     localStorage.setItem(KEY,JSON.stringify(state));
   }
   const mv=document.getElementById("masterDataVersion");
   if(mv)mv.textContent=String(rv||remote.updatedAt||"loaded");
   return true
 }catch(err){
   state.settings=state.settings||{};
   state.settings.githubLastSyncStatus="offline";
   state.settings.githubLastSyncError=String(err?.message||err);
   localStorage.setItem(KEY,JSON.stringify(state));
   const mv=document.getElementById("masterDataVersion");
   if(mv)mv.textContent="Offline · local copy";
   return false
 }
}
