const ONBOARDING_KEY="due_v11_onboarded";
let onboardingStep=0;
const onboardingSteps=[
 {type:"general",title:"Keep life admin out of your head.",text:"Track renewals, health tasks, recurring services, and future costs without turning your life into a spreadsheet."},
 {type:"document",title:"See what matters before it becomes urgent.",text:"Smart reminder windows surface documents, appointments, subscriptions, and renewals at the right time."},
 {type:"subscription",title:"Plan for the cost, not just the date.",text:"Add expected costs and Due turns future expenses into a simple monthly reserve target."}
];
function renderOnboarding(){
 const s=onboardingSteps[onboardingStep];
 E.onboardingArt.src=TYPES[s.type].icon;
 E.onboardingTitle.textContent=s.title;
 E.onboardingText.textContent=s.text;
 E.onboardingDots.innerHTML=onboardingSteps.map((_,i)=>`<span class="${i===onboardingStep?"active":""}"></span>`).join("");
 E.onboardingBackBtn.classList.toggle("hidden",onboardingStep===0);
 E.onboardingNextBtn.textContent=onboardingStep===onboardingSteps.length-1?"Start using Due":"Next";
}
function showOnboarding(){
 if(localStorage.getItem(ONBOARDING_KEY)==="1")return;
 onboardingStep=0;renderOnboarding();E.onboardingModal.classList.remove("hidden");
}
function finishOnboarding(){
 localStorage.setItem(ONBOARDING_KEY,"1");E.onboardingModal.classList.add("hidden");
}
function toast(msg){E.toast.textContent=msg;E.toast.classList.add("show");clearTimeout(window.__toast);window.__toast=setTimeout(()=>E.toast.classList.remove("show"),1700)}
function openDrawer(){renderNotifications();E.notifyDrawer.classList.add("open");E.drawerBackdrop.classList.remove("hidden")}function closeDrawer(){E.notifyDrawer.classList.remove("open");E.drawerBackdrop.classList.add("hidden")}
function maybeBrowserNotify(){if(!("Notification"in window)||Notification.permission!=="granted")return;const d=iso(today());if(state.settings.lastNotificationDate===d)return;const dueNow=state.tasks.filter(t=>{if(t.completed)return false;const n=daysUntil(t.dueDate);return n<=0||(t.reminders||[]).includes(n)}).sort((a,b)=>parse(a.dueDate)-parse(b.dueDate)).slice(0,4);if(!dueNow.length)return;try{new Notification("Due — Reminder",{body:dueNow.map(t=>`${t.title}: ${statusText(t)}`).join(" • ")})}catch{}state.settings.lastNotificationDate=d;localStorage.setItem(KEY,JSON.stringify(state))}

E.onboardingNextBtn.onclick=()=>{if(onboardingStep<onboardingSteps.length-1){onboardingStep++;renderOnboarding()}else finishOnboarding()};
E.onboardingBackBtn.onclick=()=>{if(onboardingStep>0){onboardingStep--;renderOnboarding()}};
E.skipOnboardingBtn.onclick=finishOnboarding;
E.todayText.textContent=new Intl.DateTimeFormat("en-US",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(new Date());
